import React, { useState, useMemo } from 'react';
import axios from 'axios';
import '../styles/CartPage.css';
import { API_URL_Cart_Page } from '../api';

const BASE_URL = process.env.REACT_APP_BASE_URL || 'https://polyglotacademy.am';
const IDRAM_ACCOUNT_ID = '100049302';
const PAYMENT_DESCRIPTION = 'Your purchase description';
const CUSTOMER_EMAIL = 'academy.polyglott@gmail.com';

function IdramPaymentForm({ amount, billNo }) {
    console.log('🟡 Idram Payment Form Values:', { amount, billNo });

    return (
        <form
            action="https://banking.idram.am/Payment/GetPayment"
            method="POST"
            id="idramPaymentForm"
        >
            <input type="hidden" name="EDP_LANGUAGE" value="EN" />
            <input type="hidden" name="EDP_REC_ACCOUNT" value={IDRAM_ACCOUNT_ID} />
            <input type="hidden" name="EDP_DESCRIPTION" value={PAYMENT_DESCRIPTION} />
            <input type="hidden" name="EDP_AMOUNT" value={amount} />
            <input type="hidden" name="EDP_BILL_NO" value={billNo} />
            <input type="hidden" name="EDP_EMAIL" value={CUSTOMER_EMAIL} />
            <input type="hidden" name="SUCCESS_URL" value={`${BASE_URL}/success`} />
            <input type="hidden" name="FAIL_URL" value={`${BASE_URL}/fail`} />
            <input type="hidden" name="RESULT_URL" value="https://main-api.academy-polyglot.site/result" />
        </form>
    );
}

function CartPage({ cart, updateQuantity, removeItem }) {
    const [customerInfo, setCustomerInfo] = useState({
        name: '',
        surname: '',
        phone: '',
    });
    const [modalOpen, setModalOpen] = useState(false);
    const [paymentStatus, setPaymentStatus] = useState({
        success: false,
        error: null,
    });
    const [orderId, setOrderId] = useState(null);
    const [loading, setLoading] = useState(false);

    const isFormValid = useMemo(() => {
        return (
            customerInfo.name.trim() &&
            customerInfo.surname.trim() &&
            customerInfo.phone.trim() &&
            cart.length > 0
        );
    }, [customerInfo, cart]);

    const totalAmount = useMemo(() => {
        return cart.reduce((total, item) => total + item.price * item.quantity, 0).toFixed(2);
    }, [cart]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCustomerInfo((prevInfo) => ({ ...prevInfo, [name]: value }));
    };

    const handlePayment = () => {
        setModalOpen(true);
    };

    const confirmPayment = async () => {
        setLoading(true);
        try {
            const orderData = {
                customer_name: customerInfo.name,
                customer_surname: customerInfo.surname,
                customer_phone: customerInfo.phone,
                cart,
            };

            console.log('🟡 Sending Order Data to Backend:', orderData);

            // Նախ ստուգում ենք վավերականությունը
            const isOrderValid = await verifyOrderBeforePayment(orderData);

            if (!isOrderValid) {
                console.error('❌ Order validation failed');
                setPaymentStatus({
                    success: false,
                    error: 'Order validation failed. Please check your details.'
                });
                setLoading(false);
                return;
            }

            const response = await axios.post(API_URL_Cart_Page, orderData);
            const billNo = response.data.billNo;

            console.log('🟢 Backend Response:', response.data);

            if (!billNo) {
                throw new Error('No bill number received');
            }

            setOrderId(billNo);

            // Կարճ պաուզա՝ վիճակի թարմացման համար
            await new Promise((resolve) => setTimeout(resolve, 100));

            console.log('✅ Order ID set. Preparing to submit form...');

            // Ստուգում ենք որ ֆորման առկա է
            const paymentForm = document.getElementById('idramPaymentForm');
            if (!paymentForm) {
                throw new Error('Payment form not found');
            }

            paymentForm.submit();
        } catch (error) {
            console.error('🔴 Error Confirming Payment:', error);
            setPaymentStatus({
                success: false,
                error: error.message || 'There was an issue submitting your order. Please try again.',
            });
            setLoading(false);
        }
    };

// Նոր ֆունկցիա՝ պատվերի վավերականացման համար
    const verifyOrderBeforePayment = async (orderData) => {
        // Ավելի մանրակրկիտ ստուգումներ
        if (!orderData.customer_name || orderData.customer_name.length < 2) {
            console.error('Invalid name');
            return false;
        }

        if (!orderData.customer_surname || orderData.customer_surname.length < 2) {
            console.error('Invalid surname');
            return false;
        }

        if (!orderData.customer_phone || !/^\+?[\d\s-]{10,}$/.test(orderData.customer_phone)) {
            console.error('Invalid phone number');
            return false;
        }

        if (!orderData.cart || orderData.cart.length === 0) {
            console.error('Empty cart');
            return false;
        }

        // Կարող եք ավելացնել լրացուցիչ ստուգումներ
        return true;
    };
    const cancelPayment = () => {
        setModalOpen(false);
    };

    return (
        <>
            <div className="cart-page">
                <h2>Your Cart</h2>
            </div>
            <div className="container">
                <div className="cart-page-container">


                    <div className="checkout-section">
                        <div className="customer-info">
                            <h3>Customer Information</h3>
                            <div className="input-group">
                                <label>Name</label>
                                <input
                                    type="text"
                                    name="name"
                                    placeholder="Name"
                                    value={customerInfo.name}
                                    onChange={handleInputChange}
                                />
                            </div>
                            <div className="input-group">
                                <label>Surname</label>
                                <input
                                    type="text"
                                    name="surname"
                                    placeholder="Surname"
                                    value={customerInfo.surname}
                                    onChange={handleInputChange}
                                />
                            </div>
                            <div className="input-group">
                                <label>Phone Number</label>
                                <input
                                    type="text"
                                    name="phone"
                                    placeholder="Phone Number"
                                    value={customerInfo.phone}
                                    onChange={handleInputChange}
                                />
                            </div>
                        </div>

                        <div className="cart-totals">
                            <h3>Cart Totals</h3>
                            <div className="total-row">
                                <span>Subtotal</span>
                                <span>{totalAmount} AMD</span>
                            </div>
                            <div className="total-row">
                                <span>Total</span>
                                <span>{totalAmount} AMD</span>
                            </div>
                            <button
                                className="proceed-to-checkout"
                                onClick={handlePayment}
                                disabled={!isFormValid || loading}
                            >
                                {loading ? 'Processing...' : 'Proceed To Checkout'}
                            </button>
                        </div>

                        {paymentStatus.error && (
                            <p className="error-message">{paymentStatus.error}</p>
                        )}
                        {paymentStatus.success && (
                            <p className="success-message">Payment Successful!</p>
                        )}
                    </div>
                </div>
            </div>

            {modalOpen && (
                <div className="modal-overlay">
                    <div className="modal-box">
                        <p>Please confirm your details.</p>
                        <div className="modal-buttons">
                            <button className="button" onClick={confirmPayment}>
                                Yes
                            </button>
                            <button className="button" onClick={cancelPayment}>
                                No
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <IdramPaymentForm amount={totalAmount} billNo={orderId} />
        </>
    );
}

export default CartPage;
